  Variables (sp0 : word) (argv envp : list (list byte)) (TID : Z).
  Notation usp0 := (bv_unsigned sp0).
  Notation gpv := (Z_to_bv 64 0x10800).
  Notation tpv := (Z_to_bv 64 RATP).

  Definition LO : Z := usp0 - 8388608.

  (* [comment removed for export] *)
  Definition MFRAME (mm : mem) (j8 : list byte) (s7v s6v s5v s4v : word) : Prop :=
    rw_cells usegs mm (usp0 + -128)
      [CB 8 j8; C8 s7v; C8 s6v; C8 s5v; C8 s4v; C8 (Z_to_bv 64 (envp_addr sp0 argv)); C8 (Z_to_bv 64 PMAIN);
       C8 (Z_to_bv 64 (argc argv)); C8 (Z_to_bv 64 (usp0 + 8)); C8 (Z_to_bv 64 PSTAGE2_RET)].

  Definition RSTAT (mm : mem) : Prop :=
    rw_cells usegs mm 0x3b7d8 [C8 (Z_to_bv 64 0x3b7d8); C8 (Z_to_bv 64 0x3b7d8); C8 (Z_to_bv 64 0x3b7d8); C8 (Z_to_bv 64 0); C4 (Z_to_bv 64 TID)]
    /\ rw_cells usegs mm 0x5bb08 [C4 (Z_to_bv 64 0)]
    /\ rw_cells usegs mm 0x2a530 [C8 (Z_to_bv 64 0x2a498); C8 (Z_to_bv 64 0x2a490)]
    /\ rw_cells usegs mm 0x2a490 [C8 (Z_to_bv 64 0x12d10)]
    /\ rw_cells usegs mm 0x2b798 [C1 (Z_to_bv 8 0)]
    /\ rw_cells usegs mm 0x2a4d8 [C8 (Z_to_bv 64 0x21810); C8 (Z_to_bv 64 0)]
    /\ rw_cells usegs mm 0x5bf60 [C8 (Z_to_bv 64 0)]
    /\ rw_cells usegs mm 0x5bf50 [C8 (Z_to_bv 64 0)]
    /\ rw_cells usegs mm 0x2b740 [C8 (Z_to_bv 64 0x2b658)]
    /\ rw_cells usegs mm 0x2b650 [C8 (Z_to_bv 64 0x2b568)]
    /\ rw_cells usegs mm 0x2a4e8 [C8 (Z_to_bv 64 0x2a498)]
    /\ rw_cells usegs mm 0x2a498 [C8 (Z_to_bv 64 0x2b568)]
    (* [comment removed for export] *)
    /\ rw_cells usegs mm 0x2b540 [C8 (Z_to_bv 64 0x2b540)]
    /\ (exists reg : bool, atx_state reg mm).

  (* [comment removed for export] *)
  Definition RSTATX (mm : mem) : Prop := exists reg : bool, atx_state reg mm.

  Definition rstat_addr (a : Z) : Prop :=
    (0x3b7d8 <= a < 0x3b7fc) \/ (0x5bb08 <= a < 0x5bb10) \/ (0x2a530 <= a < 0x2a540) \/ (0x2a490 <= a < 0x2a498)
    \/ (0x2b798 <= a < 0x2b799) \/ (0x2a4d8 <= a < 0x2a4e8) \/ (0x5bf50 <= a < 0x5bf58) \/ (0x5bf60 <= a < 0x5bf68)
    \/ (0x2b740 <= a < 0x2b748) \/ (0x2b650 <= a < 0x2b658) \/ (0x2a4e8 <= a < 0x2a4f0) \/ (0x2a498 <= a < 0x2a4a0)
    \/ (0x2b540 <= a < 0x2b548)
    \/ (0x5b8e8 <= a < 0x5b8e9) \/ (0x5b8ec <= a < 0x5b8f4) \/ (0x5b8f8 <= a < 0x5b910) \/ (0x5ba08 <= a < 0x5ba10) \/ (0x3b7a4 <= a < 0x3b7a5).

  Lemma atx_state_addr_rstat : forall a, atx_state_addr a -> rstat_addr a.
Proof.
